+export interface LeaseRecord { readonly id: string; readonly expiresAtMs: number; }
+
+export function selectExpiredLeaseIds(leases: readonly LeaseRecord[], nowMs: number): string[] {
+  return leases.filter((lease) => lease.expiresAtMs <= nowMs).map((lease) => lease.id);
+}
